// === Tab: sketch ===
// By Roni Kaufman
// https://ronikaufman.github.io

const N_FRAMES = 50;
let phase = 0;

let K = 35, tiles = [];
let palette = ["#ef562f", "#2b67af", "#14976b", "#f9d531", "#14976b", "#f9d531", "#ef562f", "#2b67af"];
let backCol = "#fffbe6";

function setup() {
  createCanvas(500, 500);
	stroke(5);
	strokeWeight(2);
	strokeJoin(ROUND);
	//shuffle(palette, true);

	let margin = 4;
	let t0 = {i: margin, j: margin, m: K-2*margin, n: K-2*margin, outward: true};
	tiles.push(t0);
  subdivide(t0.i, t0.j, t0.m, t0.n, random() < 1/2, t0.outward);
  for (let ti of tiles) {
    if (ti.m == 3 && ti.n == 3) {
      tiles.push({i: ti.i+1, j: ti.j+1, m: 1, n: 1, outward: !ti.outward});
    }
  }
}

function draw() {
	let t = (frameCount%N_FRAMES)/N_FRAMES;
	if (frameCount%(2*N_FRAMES) == 0) for (let ti of tiles) ti.outward = !ti.outward;
	if (t == 0) phase++;
	t = easeInOutExpo(t);

	let u = width / K, du;
	let colOffset = 0;

	if (phase%4 == 0) {
		du = t*u;
		translate(du-u/2, du-u/2);
	} else if (phase%4 == 1) {
		t = 1-t;
		du = t*u;
		translate(u/2, u/2);
	} else if (phase%4 == 2) {
		du = t*u;
		translate(u/2-du, u/2-du);
		colOffset += 4;
	} else {
		t = 1-t;
		du = t*u;
		translate(-u/2, -u/2);
		colOffset += 4;
	}

  background(backCol);

  for (let ti of tiles) {
		let x = ti.i*u, y = ti.j*u;
		let w = ti.m*u, h = ti.n*u;
		fill(backCol);
    rect(x, y, w, h);
		if (ti.outward) {
			fill(palette[0+colOffset]);
			if (phase%4 < 2) quad(x-du, y-du, x+w-du, y-du, x+w, y, x, y);
			else quad(x, y+h, x+w, y+h, x+w+du, y+h+du, x+du, y+h+du);
			fill(palette[1+colOffset]);
			if (phase%4 < 2) quad(x-du, y-du, x-du, y+h-du, x, y+h, x, y);
			else quad(x+w, y, x+w, y+h, x+w+du, y+h+du, x+w+du, y+du);
		} else {
			fill(palette[2+colOffset]);
			if (phase%4 < 2) quad(x, y+h-du, x+w-du, y+h-du, x+w, y+h, x, y+h);
			else quad(x, y, x+w, y, x+w, y+du, x+du, y+du);
			fill(palette[3+colOffset]);
			if (phase%4 < 2) quad(x+w-du, y, x+w-du, y+h-du, x+w, y+h, x+w, y);
			else quad(x, y, x, y+h, x+du, y+h, x+du, y+du);
		}
  }
}

// frontCol, topCol, leftCol
// if outward, create new trio that's not equal, 1-to-1
// else assign same value
function subdivide(i, j, m, n, horiz, outward) {
  if (horiz) {
    let m1 = 2*~~random(0, (m-3)/2) + 1;
    let m2 = m - m1 - 3;

    tiles.push({i: i+1, j: j+1, m: m1, n: n-2, outward: !outward});
    tiles.push({i: i+m1+2, j: j+1, m: m2, n: n-2, outward: !outward});

    if (n-2 > 4) {
      if (m1 > 2) subdivide(i+1, j+1, m1, n-2, !horiz, !outward);
      if (m2 > 2) subdivide(i+m1+2, j+1, m2, n-2, !horiz, !outward);
    } else if (n-2 > 2) {
      if (m1 > 4) subdivide(i+1, j+1, m1, n-2, horiz, !outward);
      if (m2 > 4) subdivide(i+m1+2, j+1, m2, n-2, horiz, !outward);
    }
  } else {
    let n1 = 2*~~random(0, (n-3)/2) + 1;
    let n2 = n - n1 - 3;

    tiles.push({i: i+1, j: j+1, m: m-2, n: n1, outward: !outward});
    tiles.push({i: i+1, j: j+n1+2, m: m-2, n: n2, outward: !outward});

    if (m-2 > 4) {
      if (n1 > 2) subdivide(i+1, j+1, m-2, n1, !horiz, !outward);
      if (n2 > 2) subdivide(i+1, j+n1+2, m-2, n2, !horiz, !outward);
    } else if (m-2 > 2) {
      if (n1 > 4) subdivide(i+1, j+1, m-2, n1, horiz, !outward);
      if (n2 > 4) subdivide(i+1, j+n1+2, m-2, n2, horiz, !outward);
    }
  }
}

// from easings.net
function easeInOutExpo(x) {
	return x === 0
		? 0
		: x === 1
		? 1
		: x < 0.5 ? Math.pow(2, 20 * x - 10) / 2
		: (2 - Math.pow(2, -20 * x + 10)) / 2;
}
